#!/bin/bash
# ====================================================================
#  mkiso-hybrid.sh  -  Gdisk v3.0 Hybrid FAT Image Compiler
# --------------------------------------------------------------------
#  Builds a bootable .iso image of the Gdisk system this script is
#  run from. Unlike the other builders there is NO ISO9660/Joliet
#  filesystem: the image is a plain MBR disk with ONE FAT32 partition
#  that holds the whole Gdisk tree.
#
#  BIOS/CSM boot: G-bootmgr single binary (spliced into this script)
#                 MBR  -> GRUB boot.img code (spliced, 512 B)
#                 LBA1 -> G-bootmgr core, embedded in the MBR gap
#                 /G-bootmgr is also copied to the FAT root
#  UEFI boot:     /EFI/BOOT/BOOTX64.EFI on the same FAT32 partition
#                 (partition type 0x0C + active flag, no separate ESP)
#
#  dd the image to a USB/SD/disk -> one readable FAT32 partition,
#  same size as the image, visible in Windows Explorer, BIOS+UEFI.
#  A fixed-VHD footer is appended (VHD_FOOTER=1, default): rename a
#  copy to .vhd and Windows mounts it natively with a double click.
#  NOTE: no El Torito - optical media (CD/DVD burning) is not supported.
#
#  Usage:
#    sudo bash mkiso-hybrid.sh                      # -> ./Gdisk-v3-hybrid.iso
#    sudo bash mkiso-hybrid.sh /path/to/output.iso  # custom output
#    EXTRA_MB=256 sudo bash mkiso-hybrid.sh         # more free space on FAT
#
#  Dependencies: dosfstools (mkfs.vfat), mtools (mcopy), util-linux (sfdisk)
#
#  Source: https://github.com/GlitchLinux/Gdisk.git
#  License: GPLv3
# ====================================================================

set -euo pipefail

export PATH="/usr/local/sbin:/usr/sbin:/sbin:$PATH"

# -------------------- config --------------------
SELF="$(readlink -f "${BASH_SOURCE[0]}")"
GDISK_SRC="$(readlink -f "$(dirname "$SELF")/../..")"
VOL_LABEL="Gdisk-v3"                 # FAT label, max 11 chars
ISO_OUTPUT="${1:-./Gdisk-v3.2-hybrid.iso}"
VHD_FOOTER="${VHD_FOOTER:-1}"
PART_START=2048                   # 1 MiB aligned, gap holds G-bootmgr core
BUILD_DIR="/tmp/gdisk-mkiso-hybrid-$$"

# -------------------- styling --------------------
RED=$'\e[0;31m'; GRN=$'\e[0;32m'; YLW=$'\e[1;33m'
CYN=$'\e[0;36m'; BOLD=$'\e[1m'; DIM=$'\e[2m'; NC=$'\e[0m'
MAGENTA=$'\033[38;5;198m'

HL="$MAGENTA"
RULE_COLOR="$DIM$CYN"

rule() {
    local w; w="$(tput cols 2>/dev/null || echo 60)"
    [ "$w" -gt 70 ] && w=70
    printf "${RULE_COLOR}%*s${NC}\n" "$w" '' | tr ' ' '-'
}

msg()  { echo -e "${GRN}[+]${NC} $*"; }
warn() { echo -e "${YLW}[!]${NC} $*"; }
err()  { echo -e "${RED}[x]${NC} $*"; }
info() { echo -e "${CYN}[i]${NC} $*"; }
die()  { err "$*"; cleanup; exit 1; }

cleanup() { rm -rf "$BUILD_DIR" 2>/dev/null || true; }
trap cleanup EXIT

# extract a base64 payload block appended at the end of this script
payload() { awk -v m="$1" '$0==m{f=1;next} /^__[A-Z0-9_]+__$/{f=0} f' "$SELF" | base64 -d; }

# write little-endian integer ($2 bytes) at byte offset $3 of file $4
put_le() {
    local val=$1 n=$2 off=$3 file=$4 i hex=""
    for ((i=0; i<n; i++)); do hex+=$(printf '\\x%02x' $(( (val >> (8*i)) & 0xff ))); done
    printf "$hex" | dd of="$file" bs=1 seek="$off" conv=notrunc status=none
}

# -------------------- banner --------------------
clear 2>/dev/null || true
echo
echo "${CYN} ${BOLD}Gdisk v3.0${NC} ❖${NC}${CYN} ${BOLD}Hybrid FAT Image Compiler${NC} ${DIM}(G-bootmgr)${NC}"
echo
rule

# -------------------- root --------------------
[ "$(id -u)" -eq 0 ] || die "Run as root:  sudo $0"

# -------------------- dependency check --------------------
need() {
    local t found
    for t in "$@"; do
        found=0
        for p in "$t" "/sbin/$t" "/usr/sbin/$t" "/usr/local/sbin/$t"; do
            command -v "$p" >/dev/null 2>&1 && { found=1; break; }
        done
        if [ "$found" -eq 0 ]; then
            case "$t" in
                mkfs.vfat)    die "missing: mkfs.vfat - install with: apt install dosfstools" ;;
                mcopy|mmd)    die "missing: $t - install with: apt install mtools" ;;
                sfdisk)       die "missing: sfdisk - install with: apt install fdisk" ;;
                *)            die "missing required tool: $t" ;;
            esac
        fi
    done
}
need mkfs.vfat mcopy mmd mdir sfdisk base64 awk dd truncate

# ====================================================================
#  Step 1: Validate source (the Gdisk system this script lives in)
# ====================================================================
echo
msg "Source: ${HL}$GDISK_SRC${NC}"
[ -f "$GDISK_SRC/boot/grub/grub.cfg" ]   || die "Source missing: boot/grub/grub.cfg"
[ -f "$GDISK_SRC/EFI/BOOT/BOOTX64.EFI" ] || die "Source missing: EFI/BOOT/BOOTX64.EFI"
[ -d "$GDISK_SRC/boot/grub/i386-pc" ]    || die "Source missing: boot/grub/i386-pc"

case "$(readlink -f "$(dirname "$ISO_OUTPUT")")/" in
    "$GDISK_SRC"/*) die "Output must be outside the source tree ($GDISK_SRC)" ;;
esac

mkdir -p "$BUILD_DIR"

# ====================================================================
#  Step 2: Unpack spliced G-bootmgr + MBR boot code
# ====================================================================
msg "Unpacking G-bootmgr..."
payload __G_BOOTMGR_B64__ > "$BUILD_DIR/G-bootmgr"
payload __BOOT_IMG_B64__  > "$BUILD_DIR/boot.img"
[ "$(stat -c%s "$BUILD_DIR/G-bootmgr")" -eq 420932 ] || die "G-bootmgr payload corrupt"
[ "$(stat -c%s "$BUILD_DIR/boot.img")"  -eq 512 ]    || die "boot.img payload corrupt"

# G-bootmgr = cdboot.img (2048 B, El Torito loader) + GRUB i386-pc core.img
tail -c +2049 "$BUILD_DIR/G-bootmgr" > "$BUILD_DIR/core.img"
CORE_BYTES=$(stat -c%s "$BUILD_DIR/core.img")
CORE_SECT=$(( (CORE_BYTES + 511) / 512 ))
[ $((1 + CORE_SECT)) -lt "$PART_START" ] || die "G-bootmgr core too big for MBR gap"
msg "G-bootmgr: $(stat -c%s "$BUILD_DIR/G-bootmgr") bytes (core $CORE_SECT sectors)"

# ====================================================================
#  Step 3: Size the FAT32 partition
# ====================================================================
# every file rounded up to a 4 KiB cluster + 4 KiB per directory, +5%, + EXTRA_MB
DATA_BYTES=$(cd "$GDISK_SRC" && find . -path ./.git -prune -o \( -type f -printf 'f %s\n' -o -type d -printf 'd 0\n' \) \
             | awk '{ if ($1=="f") s+=int(($2+4095)/4096)*4096; else s+=4096 } END { printf "%d", s }')
PART_MB=$(( DATA_BYTES * 105 / 100 / 1048576 + 1 ))
[ "$PART_MB" -lt 64 ] && PART_MB=64           # FAT32 needs >= 65525 clusters
PART_SECT=$(( PART_MB * 2048 ))
TOTAL_SECT=$(( PART_START + PART_SECT ))
msg "Payload $(( DATA_BYTES / 1048576 )) MiB -> FAT32 partition ${HL}${PART_MB} MiB${NC}"

# ====================================================================
#  Step 4: Build the FAT32 filesystem and copy the Gdisk tree
# ====================================================================
PART_IMG="$BUILD_DIR/part.img"
truncate -s $(( PART_SECT * 512 )) "$PART_IMG"
mkfs.vfat -F 32 -n "$VOL_LABEL" -h "$PART_START" "$PART_IMG" >/dev/null \
    || die "mkfs.vfat failed"

msg "Copying Gdisk tree onto FAT32..."
export MTOOLS_SKIP_CHECK=1
shopt -s nullglob dotglob
TOP=()
for e in "$GDISK_SRC"/*; do
    case "$(basename "$e")" in .git|.gitignore|.gitattributes) continue ;; esac
    TOP+=("$e")
done
shopt -u nullglob dotglob
mcopy -s -Q -m -i "$PART_IMG" "${TOP[@]}" ::/ || die "mcopy failed"
mcopy -o -Q -i "$PART_IMG" "$BUILD_DIR/G-bootmgr" ::/G-bootmgr || die "mcopy G-bootmgr failed"
msg "FAT32 populated"

# ====================================================================
#  Step 5: Assemble disk image: MBR + G-bootmgr core in gap + FAT32
# ====================================================================
msg "Assembling MBR disk image..."
OUT_TMP="$BUILD_DIR/disk.img"
truncate -s $(( PART_START * 512 )) "$OUT_TMP"
cat "$PART_IMG" >> "$OUT_TMP"
rm -f "$PART_IMG"

# single primary partition, FAT32 LBA (0x0C), active -> Windows + UEFI + BIOS friendly
printf 'label: dos\nunit: sectors\nstart=%d, size=%d, type=c, bootable\n' "$PART_START" "$PART_SECT" \
    | sfdisk -q --wipe never --no-reread --no-tell-kernel "$OUT_TMP" >/dev/null 2>&1 || die "sfdisk failed"

# MBR boot code (GRUB boot.img, bytes 0-439). Partition table untouched.
dd if="$BUILD_DIR/boot.img" of="$OUT_TMP" bs=440 count=1 conv=notrunc status=none
put_le 1 8 $((0x5c)) "$OUT_TMP"                  # boot.img kernel_sector -> LBA 1

# G-bootmgr core -> LBA 1.., patch diskboot blocklist (start LBA 2, len, seg 0x820)
dd if="$BUILD_DIR/core.img" of="$OUT_TMP" bs=512 seek=1 conv=notrunc status=none
put_le 2 8 $((512 + 0x1f4)) "$OUT_TMP"
put_le $((CORE_SECT - 1)) 2 $((512 + 0x1fc)) "$OUT_TMP"
put_le $((0x820)) 2 $((512 + 0x1fe)) "$OUT_TMP"
msg "BIOS: MBR -> LBA1 G-bootmgr core ($CORE_SECT sectors) -> /boot/grub/grub.cfg"

# ====================================================================
#  Step 6: Optional fixed-VHD footer (Windows native mount as .vhd)
# ====================================================================
if [ "$VHD_FOOTER" = "1" ]; then
    SIZE=$(( TOTAL_SECT * 512 ))
    # CHS geometry per VHD spec
    TS=$TOTAL_SECT; [ "$TS" -gt $((65535*16*255)) ] && TS=$((65535*16*255))
    if [ "$TS" -ge $((65535*16*63)) ]; then SPT=255; HDS=16; CYLH=$((TS/SPT))
    else SPT=17; CYLH=$((TS/SPT)); HDS=$(( (CYLH+1023)/1024 )); [ "$HDS" -lt 4 ] && HDS=4
        if [ "$CYLH" -ge $((HDS*1024)) ] || [ "$HDS" -gt 16 ]; then SPT=31; HDS=16; CYLH=$((TS/SPT)); fi
        if [ "$CYLH" -ge $((HDS*1024)) ]; then SPT=63; HDS=16; CYLH=$((TS/SPT)); fi
    fi
    CYL=$(( CYLH / HDS ))
    F="$BUILD_DIR/footer"; head -c 512 /dev/zero > "$F"
    printf 'conectix' | dd of="$F" conv=notrunc status=none
    be() { local v=$1 n=$2 o=$3 i h=""; for ((i=n-1;i>=0;i--)); do h+=$(printf '\\x%02x' $(( (v>>(8*i)) & 0xff ))); done
           printf "$h" | dd of="$F" bs=1 seek="$o" conv=notrunc status=none; }
    be 2 4 8; be $((0x00010000)) 4 12
    printf '\xff\xff\xff\xff\xff\xff\xff\xff' | dd of="$F" bs=1 seek=16 conv=notrunc status=none
    be $(( $(date +%s) - 946684800 )) 4 24
    printf 'gdsk' | dd of="$F" bs=1 seek=28 conv=notrunc status=none
    be $((0x00030000)) 4 32
    printf 'Wi2k' | dd of="$F" bs=1 seek=36 conv=notrunc status=none
    be "$SIZE" 8 40; be "$SIZE" 8 48
    be "$CYL" 2 56; be "$HDS" 1 58; be "$SPT" 1 59
    be 2 4 60                                            # fixed disk
    head -c 16 /dev/urandom | dd of="$F" bs=1 seek=68 conv=notrunc status=none
    SUM=$(od -An -v -tu1 "$F" | awk '{for(i=1;i<=NF;i++)s+=$i} END{print s}')
    be $(( ~SUM & 0xffffffff )) 4 64
    cat "$F" >> "$OUT_TMP"
    msg "Fixed-VHD footer appended (copy/rename to .vhd to mount in Windows)"
fi

mv -f "$OUT_TMP" "$ISO_OUTPUT" || die "could not write $ISO_OUTPUT"

# ====================================================================
#  Step 7: Result
# ====================================================================
echo
rule
msg "${BOLD}Hybrid FAT image build complete!${NC}"
rule
info "File   : ${HL}$(realpath "$ISO_OUTPUT")${NC}"
info "Size   : ${HL}$(du -h "$ISO_OUTPUT" | cut -f1)${NC}  (FAT32 partition ${PART_MB} MiB, label $VOL_LABEL)"
info "Source : ${HL}$GDISK_SRC${NC}"
echo
info "Boot methods:"
info "  BIOS : MBR -> G-bootmgr (GRUB2 core in MBR gap) -> /boot/grub/grub.cfg"
info "  UEFI : /EFI/BOOT/BOOTX64.EFI on the same FAT32 partition"
echo
info "Write to USB/SD/disk (creates ONE readable FAT32 partition):"
info "  Linux  : ${DIM}sudo dd if=$ISO_OUTPUT of=/dev/sdX bs=4M conv=fsync status=progress${NC}"
info "  Windows: ${DIM}Rufus in DD mode / Etcher / Win32DiskImager${NC}"
info "Inspect  : ${DIM}mdir -i $ISO_OUTPUT@@1M ::/${NC}"
echo
exit 0

